.resume { --font: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", "Noto Sans CJK SC", system-ui, sans-serif; --body-size: 10.5pt; --line-height: 1.3; --section-gap: 10pt; --item-gap: 3pt; --accent: #000000; --margin-top: 7mm; --margin-right: 8mm; --margin-bottom: 7mm; --margin-left: 8mm; }

