.resume li::marker { color: var(--accent); }
.resume strong, .resume b { font-weight: 600; color: var(--ink); }
.resume .photo { border-radius: 2pt; }
.resume { --font: "Source Han Serif SC", "Noto Serif SC", "Noto Serif CJK SC", "Songti SC", "STSong", "SimSun", Georgia, serif; --body-size: 9.2pt; --line-height: 1.42; --section-gap: 16pt; --item-gap: 7pt; --accent: #1B365D; --margin-top: 11mm; --margin-right: 13mm; --margin-bottom: 11mm; --margin-left: 13mm; }

