.resume { --font: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", "Noto Sans CJK SC", system-ui, sans-serif; --body-size: 9.5pt; --line-height: 1.45; --section-gap: 9pt; --item-gap: 4.5pt; --accent: #141413; --margin-top: 11mm; --margin-right: 13mm; --margin-bottom: 11mm; --margin-left: 13mm; }

css.nope:
/* Shared by the PDF and the live preview (core/resume.py). Structure only: font, sizes, gaps, margins and accent are
   CSS variables from doc.style (resume.style_vars); template files set --name / --h2 and decoration. */
.resume { position: relative; box-sizing: border-box; width: 210mm; min-height: 297mm;
  padding: var(--margin-top) var(--margin-right) var(--margin-bottom) var(--margin-left);
  background: #fff; color: var(--ink, #1d1d1f); font-family: var(--font); font-size: var(--body-size); line-height: var(--line-height);
  -webkit-font-smoothing: antialiased; }
.resume * { box-sizing: border-box; }
/* 证件照靠左、校徽靠右浮动：姓名和联系方式排在两者之间（flow-root 让它们的底线不伸到图片底下），
   第一个模块 clear 到图片下面。姓名、联系方式空着也不会让模块压到图片上。 */
.resume .photo { float: left; width: 25mm; height: 33mm; margin: 0 5mm 3mm 0; object-fit: cover; border-radius: 1.5mm; }
.resume .logo { float: right; height: 16mm; max-width: 40mm; margin: 0 0 3mm 4mm; object-fit: contain; }
.resume h1, .resume p.contact { display: flow-root; }
.resume section { clear: both; }
.resume h1 { font-size: var(--name); font-weight: 600; letter-spacing: .02em; line-height: 1.3; margin: 0 0 1.2mm; color: var(--accent); }
.resume h1 + p { margin: 0; color: var(--muted, #6e6e73); }
.resume h2 { font-size: var(--h2); font-weight: 600; color: var(--accent); margin: var(--section-gap) 0 1.6mm; padding-bottom: 1mm;
  border-bottom: .3mm solid var(--rule, #d2d2d7); }
.resume h3 { display: flex; align-items: baseline; font-size: var(--body-size); font-weight: 600; line-height: var(--line-height); margin: var(--item-gap) 0 .6mm; }
.resume h3 .seg, .resume h3 .r { font-weight: 400; }
.resume h3 .sep, .resume h3 .sep-r { font-size: 0; }
.resume h3 .sep::before { content: "·"; font-size: var(--body-size); font-weight: 400; margin: 0 1.6mm; color: var(--muted, #86868b); }
.resume h3 .r { margin-left: auto; padding-left: 4mm; color: var(--muted, #6e6e73); white-space: nowrap; font-variant-numeric: tabular-nums; }
.resume p { margin: .6mm 0; }
.resume ul, .resume ol { margin: .4mm 0; padding-left: 4.2mm; }
.resume li { margin: .3mm 0; }
.resume li p { margin: 0; }
.resume a { color: inherit; text-decoration: none; }
.resume strong, .resume b { font-weight: 600; }
.resume table { border-collapse: collapse; width: 100%; }
.resume td, .resume th { padding: .6mm 1.2mm; text-align: left; }
.resume { --name: 16.5pt; --h2: 12pt; --ink: #000; --muted: #000; --rule: #000; background: #fff; color: #000; }
.resume .photo { width: 21mm; height: 25.4mm; margin-right: 8mm; border-radius: 0; }
.resume .logo { height: 12.7mm; max-width: 47mm; }
.resume h1 { color: #000; font-weight: 700; letter-spacing: 0; line-height: 1.2; margin: 0 0 2.2mm; }
.resume h1 + p.contact { color: #000; line-height: 1.45; }
.resume h2 { color: #000; font-weight: 700; letter-spacing: 0; margin: var(--section-gap) 0 2mm; padding-bottom: .8mm; border-bottom: .75pt solid #000; }
.resume h3 { font-weight: 700; }
.resume h3 .seg, .resume h3 .r { color: #000; }
.resume h3 .sep::before { content: "-"; margin: 0; color: #000; }
.resume ul, .resume ol { padding-left: 5mm; }
.resume li::marker { color: #000; }
.resume strong, .resume b { font-weight: 700; color: #000; }
.resume { --font: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Noto Sans SC", "Noto Sans CJK SC", system-ui, sans-serif; --body-size: 10.5pt; --line-height: 1.3; --section-gap: 10pt; --item-gap: 3pt; --accent: #000000; --margin-top: 7mm; --margin-right: 8mm; --margin-bottom: 7mm; --margin-left: 8mm; }
